using System.IO.Compression;using System.Text;using System.Text.Json;using EnterpriseDocumentIntelligence.BuildingBlocks.Domain;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;
public sealed class DocumentRulesTests{[Fact]public void Create_valid_document(){var t=Guid.NewGuid();var(d,v)=DocumentRules.Create(new(t,"a.pdf","application/pdf",100,"https://blob/a","ABC"));Assert.Equal(t,d.TenantId);Assert.Equal(v.Id,d.CurrentVersionId);Assert.Equal("Processing",d.Status);}[Fact]public void Reject_invalid_inputs(){Assert.Throws<UnauthorizedAccessException>(()=>DocumentRules.Validate(new(Guid.Empty,"a","text/plain",1,"u","h")));Assert.Throws<ArgumentException>(()=>DocumentRules.Validate(new(Guid.NewGuid(),"","text/plain",1,"u","h")));Assert.Throws<ArgumentOutOfRangeException>(()=>DocumentRules.Validate(new(Guid.NewGuid(),"a","text/plain",0,"u","h")));Assert.Throws<ArgumentException>(()=>DocumentRules.Validate(new(Guid.NewGuid(),"a","x",1,"u","h")));Assert.Throws<ArgumentException>(()=>DocumentRules.Validate(new(Guid.NewGuid(),"a","text/plain",1,"","h")));Assert.Throws<ArgumentException>(()=>DocumentRules.Validate(new(Guid.NewGuid(),"a","text/plain",1,"u","")));}}
public sealed class ExtractionTests{[Fact]public async Task Extract_plain_text(){var e=new DocumentTextExtractor(new ConfigurationBuilder().Build(),new HttpClient());await using var s=new MemoryStream(Encoding.UTF8.GetBytes("hello world"));Assert.Equal("hello world",await e.ExtractAsync(s,"text/plain"));}[Fact]public async Task Extract_docx_text(){using var ms=new MemoryStream();using(var zip=new ZipArchive(ms,ZipArchiveMode.Create,true)){var entry=zip.CreateEntry("word/document.xml");await using var w=entry.Open();await w.WriteAsync(Encoding.UTF8.GetBytes("<w:document><w:p><w:t>Hello DOCX</w:t></w:p></w:document>"));}ms.Position=0;var e=new DocumentTextExtractor(new ConfigurationBuilder().Build(),new HttpClient());Assert.Contains("Hello DOCX",await e.ExtractAsync(ms,"application/vnd.openxmlformats-officedocument.wordprocessingml.document"));}[Fact]public async Task Reject_missing_document_intelligence_config(){var e=new DocumentTextExtractor(new ConfigurationBuilder().Build(),new HttpClient());await using var s=new MemoryStream([1,2,3]);await Assert.ThrowsAsync<InvalidOperationException>(()=>e.ExtractAsync(s,"application/pdf"));}}
public sealed class ChunkingTests{[Fact]public void Chunk_text_with_overlap(){var c=new SemanticChunker().Chunk("One two three. Four five six. Seven eight nine.",6,2);Assert.True(c.Count>=2);Assert.All(c,x=>Assert.InRange(x.TokenCount,1,6));}[Fact]public void Handle_empty(){Assert.Empty(new SemanticChunker().Chunk(" "));}[Fact]public void Reject_bad_limits(){Assert.Throws<ArgumentOutOfRangeException>(()=>new SemanticChunker().Chunk("x",20,0));Assert.Throws<ArgumentOutOfRangeException>(()=>new SemanticChunker().Chunk("x",100,100));}}
public sealed class EmbeddingTests{sealed class Fake:IEmbeddingClient{public int Calls;public Task<float[]>EmbedAsync(string text,CancellationToken ct=default){Calls++;if(Calls<2)throw new InvalidOperationException();return Task.FromResult(new float[]{1,2});}}[Fact]public async Task Retries_and_returns_vectors(){var f=new Fake();var s=new ResilientEmbeddingService(f,new ConfigurationBuilder().AddInMemoryCollection(new[]{new KeyValuePair<string,string?>("Embedding:MaxAttempts","2"),new("Embedding:BaseDelayMs","1")}).Build());var r=await s.EmbedAsync(new[]{new ChunkContract(Guid.NewGuid(),0,"x",1)});Assert.Single(r);Assert.Equal(2,r[0].Embedding.Length);Assert.Equal(2,f.Calls);}[Fact]public async Task Empty_input_returns_empty(){var f=new Fake();var s=new ResilientEmbeddingService(f,new ConfigurationBuilder().Build());Assert.Empty(await s.EmbedAsync([]));}}
public sealed class IndexingTests{[Fact]public void Build_index_document_with_acl(){var t=Guid.NewGuid();var d=Guid.NewGuid();var v=Guid.NewGuid();var p=Guid.NewGuid();var c=new EmbeddedChunk(Guid.NewGuid(),2,"text",1,new[]{1f,2f});var x=IndexDocumentFactory.Create(t,d,v,c,new[]{p});Assert.Equal(d.ToString(),x["DocumentId"]);Assert.Equal($"document:{d}/version:{v}/chunk:2",x["Citation"]);Assert.Contains(p.ToString(),(string[])x["AllowedPrincipalIds"]!);}}
public sealed class SearchTests{[Fact]public void Filter_contains_tenant_and_acl(){var t=Guid.NewGuid();var u=Guid.NewGuid();var f=SearchFilterBuilder.Build(t,u);Assert.Contains(t.ToString(),f);Assert.Contains(u.ToString(),f);}[Fact]public void Query_defaults(){Assert.Equal(10,new SearchQuery("hello").TopK);}}
public sealed class AgentTests{sealed class FinalModel:IAgentModel{public Task<AgentModelResponse>CompleteAsync(IReadOnlyList<(string Role,string Content)> messages,CancellationToken ct=default)=>Task.FromResult(new AgentModelResponse("answer",[],5));}[Fact]public async Task Returns_final_answer_without_tools(){var o=new AgentOrchestrator(new FinalModel(),new Dictionary<string,IAgentTool>());var r=await o.RunAsync("hello",2,1000);Assert.Equal("answer",r.Answer);Assert.Equal(0,r.ToolCalls);}sealed class FakeTool:IAgentTool{public string Name=>"search";public Task<string>ExecuteAsync(string a,CancellationToken c=default)=>Task.FromResult("CITATION: doc:1\ntext");}sealed class ToolModel:IAgentModel{int i;public Task<AgentModelResponse>CompleteAsync(IReadOnlyList<(string Role,string Content)> m,CancellationToken c=default){i++;return Task.FromResult(i==1?new AgentModelResponse(null,new[]{new AgentToolCall("search","{}")} ,1):new AgentModelResponse("done",[],2));}}[Fact]public async Task Executes_tool_and_collects_citation(){var o=new AgentOrchestrator(new ToolModel(),new Dictionary<string,IAgentTool>{{"search",new FakeTool()}});var r=await o.RunAsync("hello",2,1000);Assert.Equal(1,r.ToolCalls);Assert.Contains("doc:1",r.Citations);}}
public sealed class McpTests{sealed class H:IMcpHandler{public string ToolName=>"x";public Task<object>ExecuteAsync(JsonElement a,CancellationToken c=default)=>Task.FromResult<object>("ok");}[Fact]public async Task Router_lists_and_executes(){var r=new McpToolRouter(new[]{new H()});Assert.Single(r.List());var result=await r.ExecuteAsync("x",JsonDocument.Parse("{}").RootElement);Assert.Equal("ok",result);}[Fact]public async Task Router_rejects_unknown(){var r=new McpToolRouter([]);await Assert.ThrowsAsync<KeyNotFoundException>(()=>r.ExecuteAsync("x",JsonDocument.Parse("{}").RootElement));}}
public sealed class AuditTests{[Fact]public void Create_valid_event(){var c=new AuditCommand(Guid.NewGuid(),Guid.NewGuid(),"READ","Document",Guid.NewGuid(),"Success","c",null);var e=AuditRules.Create(c);Assert.Equal("READ",e.Action);}[Fact]public void Reject_invalid(){Assert.Throws<ArgumentException>(()=>AuditRules.Validate(new(Guid.Empty,null,"A","R",null,"O",null,null)));Assert.Throws<ArgumentException>(()=>AuditRules.Validate(new(Guid.NewGuid(),null,"","R",null,"O",null,null)));Assert.Throws<ArgumentException>(()=>AuditRules.Validate(new(Guid.NewGuid(),null,"A","",null,"O",null,null)));Assert.Throws<ArgumentException>(()=>AuditRules.Validate(new(Guid.NewGuid(),null,"A","R",null,"",null,null)));}}
public sealed class SharedInfrastructureTests{[Fact]public void Outbox_lifecycle(){var x=new OutboxMessage("t","{}","c");Assert.False(x.IsPublished);x.MarkAttempt("e");Assert.Equal(1,x.Attempts);x.MarkPublished();Assert.True(x.IsPublished);}[Fact]public void Idempotency_expiry(){var x=new IdempotencyRecord("k",TimeSpan.FromMinutes(1));Assert.False(x.IsExpired(DateTimeOffset.UtcNow));Assert.True(x.IsExpired(x.ExpiresAt));}}

public sealed class AdditionalCoverageTests{[Fact]public void Document_rules_reject_oversize(){Assert.Throws<ArgumentOutOfRangeException>(()=>DocumentRules.Validate(new(Guid.NewGuid(),"x.pdf","application/pdf",524288001,"u","h")));}[Fact]public void Chunker_handles_long_word(){var r=new SemanticChunker().Chunk(string.Join(' ',Enumerable.Repeat("word",120)),50,5);Assert.True(r.Count>=3);}[Fact]public async Task Embedding_failure_after_retries_throws(){var f=new AlwaysFailEmbedding();var s=new ResilientEmbeddingService(f,new ConfigurationBuilder().AddInMemoryCollection(new[]{new KeyValuePair<string,string?>("Embedding:MaxAttempts","2"),new("Embedding:BaseDelayMs","1")}).Build());await Assert.ThrowsAsync<InvalidOperationException>(()=>s.EmbedAsync(new[]{new ChunkContract(Guid.NewGuid(),0,"x",1)}));}sealed class AlwaysFailEmbedding:IEmbeddingClient{public Task<float[]>EmbedAsync(string t,CancellationToken c=default)=>throw new InvalidOperationException("fail");}[Fact]public void Indexing_builder_builds_all_chunks(){var input=new EmbeddingsCreated(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),new[]{new EmbeddedChunk(Guid.NewGuid(),0,"a",1,new[]{1f}),new EmbeddedChunk(Guid.NewGuid(),1,"b",1,new[]{2f})},DateTimeOffset.UtcNow,"c");var result=new IndexingBatchBuilder().Build(input);Assert.Equal(2,result.Count);}[Fact]public async Task Agent_unknown_tool_is_rejected(){var m=new ToolRequestModel();var o=new AgentOrchestrator(m,new Dictionary<string,IAgentTool>());await Assert.ThrowsAsync<InvalidOperationException>(()=>o.RunAsync("x",2,1000));}sealed class ToolRequestModel:IAgentModel{public Task<AgentModelResponse>CompleteAsync(IReadOnlyList<(string Role,string Content)> m,CancellationToken c=default)=>Task.FromResult(new AgentModelResponse(null,new[]{new AgentToolCall("missing","{}")},1));}[Fact]public async Task Agent_budget_is_enforced(){var m=new ToolRequestModel2();var o=new AgentOrchestrator(m,new Dictionary<string,IAgentTool>{{"x",new FakeAgentTool()}});await Assert.ThrowsAsync<InvalidOperationException>(()=>o.RunAsync("x",0,1000));}sealed class ToolRequestModel2:IAgentModel{public Task<AgentModelResponse>CompleteAsync(IReadOnlyList<(string Role,string Content)> m,CancellationToken c=default)=>Task.FromResult(new AgentModelResponse(null,new[]{new AgentToolCall("x","{}")},1));}sealed class FakeAgentTool:IAgentTool{public string Name=>"x";public Task<string>ExecuteAsync(string a,CancellationToken c=default)=>Task.FromResult("ok");}[Fact]public async Task Mcp_rejects_oversized_arguments(){var r=new McpToolRouter(new[]{new FakeMcpHandler()});using var doc=JsonDocument.Parse("{}");await Assert.ThrowsAsync<ArgumentException>(()=>r.ExecuteAsync("x",JsonDocument.Parse("{\\"data\\":\\""+new string('a',33000)+"\\"}").RootElement));}sealed class FakeMcpHandler:IMcpHandler{public string ToolName=>"x";public Task<object>ExecuteAsync(JsonElement a,CancellationToken c=default)=>Task.FromResult<object>("ok");}[Fact]public void Outbox_rejects_empty_topic(){Assert.Throws<ArgumentException>(()=>new OutboxMessage("","{}","c"));Assert.Throws<ArgumentException>(()=>new OutboxMessage("t","","c"));}[Fact]public void Idempotency_rejects_bad_ttl(){Assert.Throws<ArgumentOutOfRangeException>(()=>new IdempotencyRecord("k",TimeSpan.Zero));}}
